"""Minimal CloudFormation: private site, API/Lambda, Bedrock and daily quota."""
import json
from pathlib import Path
ref=lambda k:{'Ref':k}
get=lambda r,k:{'Fn::GetAtt':[r,k]}
sub=lambda s:{'Fn::Sub':s}
resources={}
resources['SiteBucket']={'Type':'AWS::S3::Bucket','Properties':{'PublicAccessBlockConfiguration':{'BlockPublicAcls':True,'BlockPublicPolicy':True,'IgnorePublicAcls':True,'RestrictPublicBuckets':True},'BucketEncryption':{'ServerSideEncryptionConfiguration':[{'ServerSideEncryptionByDefault':{'SSEAlgorithm':'AES256'}}]}}}
resources['Quota']={'Type':'AWS::DynamoDB::Table','Properties':{'BillingMode':'PAY_PER_REQUEST','AttributeDefinitions':[{'AttributeName':'id','AttributeType':'S'}],'KeySchema':[{'AttributeName':'id','KeyType':'HASH'}],'TimeToLiveSpecification':{'AttributeName':'expiresAt','Enabled':True}}}
resources['LogGroup']={'Type':'AWS::Logs::LogGroup','Properties':{'LogGroupName':sub('/aws/lambda/${AWS::StackName}-query'),'RetentionInDays':7}}
resources['Role']={'Type':'AWS::IAM::Role','Properties':{'AssumeRolePolicyDocument':{'Version':'2012-10-17','Statement':[{'Effect':'Allow','Principal':{'Service':'lambda.amazonaws.com'},'Action':'sts:AssumeRole'}]},'Policies':[{'PolicyName':'ReadOnlyQueryRuntime','PolicyDocument':{'Version':'2012-10-17','Statement':[{'Effect':'Allow','Action':['logs:CreateLogStream','logs:PutLogEvents'],'Resource':sub('${LogGroup.Arn}:*')},{'Effect':'Allow','Action':'bedrock:InvokeModel','Resource':sub('arn:${AWS::Partition}:bedrock:${AWS::Region}::foundation-model/${ModelId}')},{'Effect':'Allow','Action':'dynamodb:UpdateItem','Resource':get('Quota','Arn')}]}}]}}
resources['Function']={'Type':'AWS::Lambda::Function','DependsOn':'LogGroup','Properties':{'FunctionName':sub('${AWS::StackName}-query'),'Runtime':'python3.12','Architectures':['arm64'],'Handler':'app.handler','MemorySize':1024,'Timeout':28,'Role':get('Role','Arn'),'Code':{'S3Bucket':ref('ArtifactBucket'),'S3Key':ref('ArtifactKey')},'Environment':{'Variables':{'BEDROCK_MODEL_ID':ref('ModelId'),'HOSPITAL_DATA_DIR':'/var/task/data','DAILY_AI_LIMIT':ref('DailyAiLimit'),'QUOTA_TABLE':ref('Quota')}}}}
resources['Api']={'Type':'AWS::ApiGatewayV2::Api','Properties':{'Name':sub('${AWS::StackName}-api'),'ProtocolType':'HTTP','CorsConfiguration':{'AllowOrigins':['https://snfbenchmarking.com','https://www.snfbenchmarking.com','http://127.0.0.1:8765'],'AllowMethods':['GET','POST','OPTIONS'],'AllowHeaders':['content-type'],'MaxAge':600}}}
resources['Integration']={'Type':'AWS::ApiGatewayV2::Integration','Properties':{'ApiId':ref('Api'),'IntegrationType':'AWS_PROXY','IntegrationUri':get('Function','Arn'),'PayloadFormatVersion':'2.0','TimeoutInMillis':29000}}
for name,key in [('Health','GET /api/health'),('Query','POST /api/query'),('Chat','POST /api/chat'),('Provider','POST /api/provider'),('Network','POST /api/network')]:resources[name+'Route']={'Type':'AWS::ApiGatewayV2::Route','Properties':{'ApiId':ref('Api'),'RouteKey':key,'Target':{'Fn::Join':['/',['integrations',ref('Integration')]]}}}
resources['Stage']={'Type':'AWS::ApiGatewayV2::Stage','Properties':{'ApiId':ref('Api'),'StageName':'$default','AutoDeploy':True,'DefaultRouteSettings':{'ThrottlingBurstLimit':5,'ThrottlingRateLimit':2}}}
resources['Permission']={'Type':'AWS::Lambda::Permission','Properties':{'Action':'lambda:InvokeFunction','FunctionName':ref('Function'),'Principal':'apigateway.amazonaws.com','SourceArn':sub('arn:${AWS::Partition}:execute-api:${AWS::Region}:${AWS::AccountId}:${Api}/*')}}
resources['OAC']={'Type':'AWS::CloudFront::OriginAccessControl','Properties':{'OriginAccessControlConfig':{'Name':sub('${AWS::StackName}-oac'),'OriginAccessControlOriginType':'s3','SigningBehavior':'always','SigningProtocol':'sigv4'}}}
resources['Rewrite']={'Type':'AWS::CloudFront::Function','Properties':{'Name':sub('${AWS::StackName}-index'),'AutoPublish':True,'FunctionConfig':{'Comment':'Static directory indexes only','Runtime':'cloudfront-js-2.0'},'FunctionCode':"function handler(event) { var r=event.request;if(r.uri.endsWith('/'))r.uri+='index.html';else if(r.uri.split('/').pop().indexOf('.')<0)r.uri+='/index.html';return r;}"}}
resources['Distribution']={'Type':'AWS::CloudFront::Distribution','Properties':{'DistributionConfig':{'Enabled':True,'DefaultRootObject':'index.html','HttpVersion':'http2and3','PriceClass':'PriceClass_100','Origins':[{'Id':'site','DomainName':get('SiteBucket','RegionalDomainName'),'OriginAccessControlId':get('OAC','Id'),'S3OriginConfig':{'OriginAccessIdentity':''}},{'Id':'api','DomainName':sub('${Api}.execute-api.${AWS::Region}.amazonaws.com'),'CustomOriginConfig':{'OriginProtocolPolicy':'https-only','HTTPSPort':443,'OriginSSLProtocols':['TLSv1.2']}}],'DefaultCacheBehavior':{'TargetOriginId':'site','ViewerProtocolPolicy':'redirect-to-https','AllowedMethods':['GET','HEAD','OPTIONS'],'CachePolicyId':'658327ea-f89d-4fab-a63d-7e88639e58f6','Compress':True,'FunctionAssociations':[{'EventType':'viewer-request','FunctionARN':get('Rewrite','FunctionMetadata.FunctionARN')}]},'CacheBehaviors':[{'PathPattern':'api/*','TargetOriginId':'api','ViewerProtocolPolicy':'https-only','AllowedMethods':['GET','HEAD','OPTIONS','PUT','POST','PATCH','DELETE'],'CachePolicyId':'4135ea2d-6df8-44a3-9df3-4b5a84be39ad','OriginRequestPolicyId':'b689b0a8-53d0-40ab-baf2-68738e2966ac','Compress':True}],'ViewerCertificate':{'CloudFrontDefaultCertificate':True}}}}
resources['BucketPolicy']={'Type':'AWS::S3::BucketPolicy','Properties':{'Bucket':ref('SiteBucket'),'PolicyDocument':{'Version':'2012-10-17','Statement':[{'Effect':'Allow','Principal':{'Service':'cloudfront.amazonaws.com'},'Action':'s3:GetObject','Resource':sub('${SiteBucket.Arn}/*'),'Condition':{'StringEquals':{'AWS:SourceArn':sub('arn:${AWS::Partition}:cloudfront::${AWS::AccountId}:distribution/${Distribution}')}}}]}}}
t={'AWSTemplateFormatVersion':'2010-09-09','Description':'HCRIS draft semantic analytics and Bedrock question service; no production DNS changes.','Parameters':{'ArtifactBucket':{'Type':'String'},'ArtifactKey':{'Type':'String'},'ModelId':{'Type':'String','Default':'mistral.mistral-large-3-675b-instruct'},'DailyAiLimit':{'Type':'Number','Default':50,'MinValue':1,'MaxValue':1000}},'Resources':resources,'Outputs':{'SiteBucket':{'Value':ref('SiteBucket')},'DistributionId':{'Value':ref('Distribution')},'DraftUrl':{'Value':sub('https://${Distribution.DomainName}/hospitals/lab/')},'ApiBase':{'Value':sub('https://${Distribution.DomainName}')},'FunctionName':{'Value':ref('Function')}}}
(Path(__file__).parent/'hcris-draft.json').write_text(json.dumps(t,indent=2)+'\n')
